const f = $input.first().json;
const arten = { "Wartung einschalten": "maintenance", "Störung einschalten": "incident", "Hinweis einschalten": "info" };
const dauern = { "1 Stunde": 1, "4 Stunden": 4, "1 Tag": 24, "3 Tage": 72 };
const aktiv = f["Aktion"] in arten;
const roh = f["Bereiche"];
const gewaehlt = Array.isArray(roh) ? roh : String(roh || "").split(",");
const frei = String(f["Weitere Bereiche"] || "").split(/[,;\n]/);
const bereiche = [...new Set([...gewaehlt, ...frei].map((s) => s.trim().slice(0, 40)).filter(Boolean))].slice(0, 12).join(", ");
const stunden = dauern[f["Dauer"]];
const bis = aktiv && stunden ? new Date(Date.now() + stunden * 3600000).toISOString() : "";
const text = (f["Text"] || "").trim() || "Ich arbeite gerade am Server und an der Website, es kann zu Ausfällen kommen.";
return [{ json: { ref: "main", inputs: { aktiv: String(aktiv), art: arten[f["Aktion"]] || "maintenance", titel: "", text, bis, bereiche } } }];

const MAIL_AN = 'peter.kretzer@dlrg.org';
const MAIL_VON = 'n8n@pkr-service.de';
const ID_ZEILE = 'ID-IT-xi8klGKdh8';
const SCHRIFT = "-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const FARBEN = { rot: '#c8102e', amber: '#b45309', gruen: '#15803d', blau: '#1d4ed8', grau: '#475569', indigo: '#4338ca' };
const mitId = (text) => String(text).replace(/\s+$/, '') + '\n\n' + ID_ZEILE;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const verlinken = (s) => esc(s).replace(/(https?:\/\/[^\s<]*[^\s<.,;:!?)])/g, '<a href="$1" style="color:#1d4ed8;text-decoration:underline">$1</a>');
const absaetze = (text) => String(text).replace(/\r\n?/g, '\n').split(/\n{2,}/).filter((b) => b.trim()).map((b) => '<p style="margin:0 0 14px 0;line-height:1.6">' + verlinken(b.trim()).replace(/\n/g, '<br>') + '</p>').join('');
const felder = (zeilen) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:0 0 18px 0;border:1px solid #e5e7eb">' + zeilen.map(([k, v], i) => '<tr style="background:' + (i % 2 ? '#ffffff' : '#f9fafb') + '"><td valign="top" style="padding:9px 12px;width:34%;font-size:13px;color:#6b7280;border-bottom:1px solid #eef0f3">' + esc(k) + '</td><td valign="top" style="padding:9px 12px;font-size:14px;color:#111827;border-bottom:1px solid #eef0f3">' + verlinken(v) + '</td></tr>').join('') + '</table>';
const box = (inhalt, farbe, titel) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 18px 0"><tr><td style="border-left:4px solid ' + farbe + ';background:#f9fafb;padding:14px 16px">' + (titel ? '<div style="font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:' + farbe + ';margin-bottom:8px">' + esc(titel) + '</div>' : '') + inhalt + '</td></tr></table>';
const liste = (eintraege) => '<ul style="margin:0;padding:0 0 0 18px;line-height:1.6">' + eintraege.map((e) => '<li style="margin:0 0 4px 0">' + verlinken(e) + '</li>').join('') + '</ul>';
const knopf = (text, url, farbe) => '<table role="presentation" cellpadding="0" cellspacing="0" style="margin:4px 0 18px 0"><tr><td style="background:' + farbe + ';border-radius:6px"><a href="' + esc(url) + '" style="display:inline-block;padding:11px 20px;font-size:14px;font-weight:600;color:#ffffff;text-decoration:none">' + esc(text) + '</a></td></tr></table>';
const klein = (text) => '<p style="margin:6px 0 14px 0;font-size:13px;line-height:1.5;color:#6b7280">' + verlinken(text).replace(/\n/g, '<br>') + '</p>';
const datum = (iso, kurz) => {
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? String(iso) : d.toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: kurz ? 'short' : 'medium' }) + ' Uhr';
};
const layout = ({ label, farbe, titel, badge, vorschau, abschnitte }) => {
  const zeit = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: 'short' });
  const plakette = badge ? '<div style="margin-top:12px"><span style="display:inline-block;background:#ffffff;color:' + farbe + ';font-size:12px;font-weight:700;padding:4px 10px;border-radius:12px">' + esc(badge) + '</span></div>' : '';
  return '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>' + esc(titel) + '</title></head>'
    + '<body style="margin:0;padding:0;background:#f3f4f6;font-family:' + SCHRIFT + '">'
    + '<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:#f3f4f6">' + esc(vorschau || titel) + '</div>'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6"><tr><td align="center" style="padding:24px 12px">'
    + '<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden">'
    + '<tr><td style="background:' + farbe + ';padding:22px 26px"><div style="font-size:12px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:#ffffff;opacity:.9">' + esc(label) + '</div>'
    + '<div style="margin-top:6px;font-size:22px;line-height:1.3;font-weight:700;color:#ffffff">' + esc(titel) + '</div>' + plakette + '</td></tr>'
    + '<tr><td style="padding:24px 26px 12px 26px;font-size:15px;line-height:1.6;color:#1f2937">' + abschnitte.join('') + '</td></tr>'
    + '<tr><td style="padding:14px 26px;background:#f9fafb;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.6;color:#6b7280">Automatisch gesendet von n8n am ' + esc(zeit) + ' Uhr<div style="color:#9ca3af">' + ID_ZEILE + '</div></td></tr>'
    + '</table></td></tr></table></body></html>';
};
const f = $('Formular').first().json;
const i = $input.first().json.inputs;
const an = i.aktiv === 'true';
const bis = i.bis ? datum(i.bis, true) : 'offen';
const zeilen = an
  ? [
    'Der Status-Hinweis auf edv-kretzer.de wurde eingeschaltet.',
    '',
    'Aktion: ' + f['Aktion'],
    'Bereiche: ' + (i.bereiche || '-'),
    'Text: ' + i.text,
    'Gültig bis: ' + bis,
    '',
    'Sichtbar nach ca. einer Minute.',
  ]
  : [
    'Der Status-Hinweis auf edv-kretzer.de wurde ausgeschaltet.',
    '',
    'Sichtbar nach ca. einer Minute.',
  ];
const farbe = !an ? FARBEN.gruen : i.art === 'incident' ? FARBEN.rot : i.art === 'info' ? FARBEN.blau : FARBEN.amber;
const abschnitte = an
  ? [
    felder([['Bereiche', i.bereiche || '-'], ['Gültig bis', bis]]),
    box(absaetze(i.text), farbe, 'Text auf der Website'),
    knopf('Website öffnen', 'https://edv-kretzer.de', farbe),
    klein('Der Hinweis ist nach ca. einer Minute sichtbar.'),
  ]
  : [
    absaetze('Der Status-Hinweis auf edv-kretzer.de wurde ausgeschaltet.'),
    knopf('Website öffnen', 'https://edv-kretzer.de', farbe),
    klein('Die Änderung ist nach ca. einer Minute sichtbar.'),
  ];
const html = layout({
  label: 'edv-kretzer.de · Status-Hinweis',
  farbe,
  titel: f['Aktion'],
  badge: an ? 'Eingeschaltet' : 'Ausgeschaltet',
  vorschau: an ? i.text : 'Status-Hinweis ausgeschaltet',
  abschnitte,
});
return [{ json: { mailAn: MAIL_AN, mailVon: MAIL_VON, betreff: 'Status-Hinweis: ' + f['Aktion'] + (an && i.bereiche ? ' (' + i.bereiche + ')' : ''), text: mitId(zeilen.join('\n')), html } }];
